export const discardRestOfPacket = (iterator) => {
    const next188 = 188 - (iterator.counter.getOffset() % 188);
    iterator.discard(next188);
};
export const getRestOfPacket = (iterator) => {
    const next188 = 188 - (iterator.counter.getOffset() % 188);
    return iterator.getSlice(next188);
};
